export function measureDimension(dimensions,key,value){if(!dimensions[key]||!Number.isFinite(value)||value<=0)throw Error('Medición inválida');if(dimensions[key].status==='FROZEN')throw Error('Descongelar explícitamente antes de editar');dimensions[key]={...dimensions[key],value,status:'MEASURED',entered_at:new Date().toISOString(),source:'USER_ENTERED'};}
export function freezeDimension(dimensions,key){if(dimensions[key]?.status!=='MEASURED')throw Error('Primero introducir medición');dimensions[key].status='FROZEN';}
export function interferenceAudit(d){const v=k=>d[k].value;const uncertain=Object.values(d).some(x=>x.status!=='FROZEN');const tested=(id,title,margin,scope)=>({id,title,margin_mm:Math.round(margin*10)/10,status:margin<0?'RISK':uncertain?'TBC-MEDIR':'PASS',scope});return [tested('A','Rotor vs carcasa',Math.min(v('cabinet_width_mm'),v('cabinet_depth_mm'))/2-Math.sqrt(v('rotor_radius_mm')**2+v('rotor_halfwidth_mm')**2)-10,'Envolvente circular conservadora; no CAD exacto'),tested('B','Rotor vs boca bins',v('rotor_outlet_y_mm')-Math.max(...[0,1,2,3].map(i=>v(`bin${i}_height_mm`)))-20,'Altura libre; falta asas y flexión'),tested('C','Hoja vs entrada guía',v('tray_y_mm')-v('gate_width_mm')-v('rotor_inlet_y_mm'),'Solape de envolventes verticales exige barrido 3D, no prueba de colisión por sí solo'),tested('D','Bins y espacio central',v('cabinet_width_mm')-v('bin0_width_mm')-v('bin1_width_mm')-60,'Ancho estático; faltan asas y paso extracción'),tested('E','Electrónica posterior y barrido',v('cabinet_depth_mm')/2-v('electronic_bay_depth_mm')-Math.sqrt(v('rotor_radius_mm')**2+v('rotor_halfwidth_mm')**2),'Envolvente conservadora puede cruzar bahía'),{id:'F',title:'Servo, varilla, bisagra y punto muerto',status:'TBC-MEDIR',scope:'Longitudes y brazos reales pendientes; simulación de referencia no resuelve contacto'},{id:'G',title:'Tapa, cámara, puerta y retirada de bins',status:'TBC-MEDIR',scope:'Bisagras animadas; recorrido de extracción requiere maqueta'},{id:'H',title:'CSI, arnés y ventilación',status:'TBC-MEDIR',scope:`Ruta CSI ${v('csi_route_length_mm')} mm referencia; radio mínimo sin ficha`},{id:'I',title:'Centro de gravedad y vuelco',status:'TBC-MEDIR',scope:`Masa ${v('cabinet_mass_kg')} kg y CG ${v('cg_height_mm')} mm son referencias`},{id:'J',title:'Cadena de corte y feedback 3.3 V',status:'BLOCKER',scope:'Interfaces no especificadas por BOM; ver HARDWARE-RISK-01..05'}];}
export function traceWires(wires,start,end){const queue=[[start,[]]],seen=new Set();while(queue.length){const [node,path]=queue.shift();if(node===end)return path;if(seen.has(node))continue;seen.add(node);for(const w of wires.filter(w=>w.from_component===node))queue.push([w.to_component,[...path,w.id]]);}return [];}
export function completeCommissionStep(progress,definitions,index){const c=definitions[index];if(index>0&&!progress[definitions[index-1].id]?.completed)throw Error('Completar etapa anterior');if(!c.checks.every(x=>progress[c.id]?.checks?.[x]))throw Error('Marcar todos los checks');progress[c.id].completed=true;progress[c.id].source='SIMULATION';progress[c.id].physical_result=null;}
